-- Own transaction-local catalogue: bootstrap metadata remains historical and is
-- restored by rollback; opening must include EVERY active classified target.
update public.escopos set ativo=false where tipo is not null and id not in (pg_temp.fixture('unit'),pg_temp.fixture('district'));
