select has_function('public','schedule_demo_rule',array['jsonb','text','date','text','uuid'],'future rule command exists');
select has_function('public','reassign_demo_position',array['jsonb','uuid','integer','jsonb','text','uuid'],'assignment command exists');
insert into auth.users(id,email,aud,role) select pg_temp.fixture(who),who||'-t13@example.invalid','authenticated','authenticated' from unnest(array['admin','new-actor','new-reviewer','legacy-reader','cam','outsider'])who;
insert into public.vinculos(actor_id,papel,escopo_id) values(pg_temp.fixture('legacy-reader'),'area_tecnica','c0de0000-0000-4000-8000-000000000003');
insert into public.contas_demo(ator_id,rotulo) select pg_temp.fixture(who),'DEMO-'||who from unnest(array['admin','actor','reviewer','new-actor','new-reviewer','cam'])who;
update public.vinculos set indicador_id='c0de0000-0000-4000-8000-000000000002',vigencia_inicio=current_date-1 where actor_id=pg_temp.fixture('actor');
insert into public.vinculos(actor_id,papel,escopo_id,indicador_id,vigencia_inicio)
select pg_temp.fixture(who),role_name,pg_temp.fixture(scope),'c0de0000-0000-4000-8000-000000000002',current_date-1 from (values
 ('admin','administrador','district'),('actor','area_tecnica','district'),('reviewer','revisor_tecnico','unit'),('reviewer','revisor_tecnico','district'),
 ('new-actor','area_tecnica','unit'),('new-reviewer','revisor_tecnico','unit'),('cam','cam','unit'),('cam','cam','district'),('admin','area_tecnica','unit'))v(who,role_name,scope);
update public.entradas set revisao_atual_id=pg_temp.fixture('draft') where id=pg_temp.fixture('entry');
insert into public.territorios_competencia(competencia_id,unidade_id,distrito_id) values(pg_temp.fixture('competence'),pg_temp.fixture('unit'),pg_temp.fixture('district'));
create function pg_temp.ctx(who text,month_id uuid default null,scope text default 'unit') returns jsonb language sql security definer as $$select jsonb_build_object('vinculoId',id,'competenciaId',coalesce(month_id,pg_temp.fixture('competence')),'indicadorId',indicador_id) from public.vinculos where actor_id=pg_temp.fixture(who) and escopo_id=pg_temp.fixture(case when who='admin' then 'district' else scope end) and indicador_id is not null;$$;
create function pg_temp.assignments() returns jsonb language sql as $$select jsonb_agg(jsonb_build_object('escopoId',pg_temp.fixture(scope),'informanteId',pg_temp.fixture('actor'),'revisorId',pg_temp.fixture('reviewer'),'aplicavel',true) order by scope) from unnest(array['unit','district'])scope;$$;
create function pg_temp.config_count(tab text) returns bigint language sql security definer as $$select case tab when 'competences' then (select count(*) from public.competencias where modelo=2) when 'operations' then (select count(*) from public.operacoes_dominio) when 'rules' then (select count(*) from public.regras) end;$$;
create function pg_temp.position(month_id uuid,scope text default 'unit') returns uuid language sql security definer as $$select id from public.posicoes_esperadas where competencia_id=month_id and alvo_id=pg_temp.fixture(scope);$$;
create function pg_temp.input(value text default '10') returns jsonb language sql as $$select jsonb_build_object('estadoDado','valor','valor',value,'fonte','T13 ficticia','periodoFonte','2026-11-01','motivo','');$$;
create temporary table saved(label text primary key,receipt jsonb);
grant select,insert on saved to authenticated;
create function pg_temp.november() returns uuid language sql security definer as $$select (receipt->>'resourceId')::uuid from pg_temp.saved where label='november';$$;
select pg_temp.login_as('admin');set local role authenticated;
select throws_ok($$select public.open_demo_competence(pg_temp.ctx('admin'),'infinity',pg_temp.assignments(),gen_random_uuid())$$,'22023','invalid_input','non-finite month rejected at command boundary');
