select throws_ok($$select public.open_demo_competence(pg_temp.ctx('admin'),'2026-11-01',jsonb_build_array(jsonb_build_object('escopoId',pg_temp.fixture('unit'),'informanteId',pg_temp.fixture('actor'),'revisorId',pg_temp.fixture('actor'),'aplicavel',true)),gen_random_uuid())$$,'22023','invalid_input','same actor cannot be informant and reviewer');
select throws_ok($$select public.open_demo_competence(pg_temp.ctx('admin'),'2026-11-01',jsonb_build_array(jsonb_build_object('escopoId',pg_temp.fixture('unit'),'informanteId',pg_temp.fixture('admin'),'revisorId',pg_temp.fixture('reviewer'),'aplicavel',true)),gen_random_uuid())$$,'42501','access_denied','opening is not indirect self privilege');
