select throws_ok($$select public.schedule_demo_rule(pg_temp.ctx('admin'),'0.75','2026-10-01','DEMO-APROVACAO-V2',gen_random_uuid())$$,'22023','invalid_input','activation cannot affect an opened month');
select throws_ok($$select public.schedule_demo_rule(pg_temp.ctx('admin'),'0.75','2026-11-02','DEMO-APROVACAO-V2',gen_random_uuid())$$,'22023','invalid_input','activation requires first day');
select throws_ok($$select public.schedule_demo_rule(pg_temp.ctx('admin'),'0','2026-11-01','DEMO-APROVACAO-V2',gen_random_uuid())$$,'22023','invalid_input','zero factor rejected');
select throws_ok($$select public.schedule_demo_rule(pg_temp.ctx('admin'),'0.75','2026-11-01',E'\t \n',gen_random_uuid())$$,'22023','invalid_input','empty approval reference rejected');
