select is(public.schedule_demo_rule(pg_temp.ctx('admin'),'0.75','2026-11-01',' DEMO-APROVACAO-V2 ',pg_temp.fixture('schedule-op')),(select receipt from saved where label='rule'),'canonical rule retry is exact');
select throws_ok($$select public.schedule_demo_rule(pg_temp.ctx('admin'),'0.9','2026-11-01','DEMO-APROVACAO-V2',pg_temp.fixture('schedule-op'))$$,'22023','operation_payload_mismatch','same key cannot change factor');
select throws_ok($$select public.schedule_demo_rule(pg_temp.ctx('admin'),'0.9','2026-11-01','DEMO-APROVACAO-OTHER',gen_random_uuid())$$,'22023','invalid_input','same activation month cannot be duplicated');
