select is((select trim_scale(fator)::text from public.regras where date '2026-11-01'>=vigencia_inicio and (vigencia_fim is null or date '2026-11-01'<=vigencia_fim)),'0.8','legacy November temporal reader still selects original0.8');
select pg_temp.login_as('admin');
select throws_ok($$select public.open_demo_competence(pg_temp.ctx('admin'),'2026-11-01',jsonb_build_array(pg_temp.assignments()->0),gen_random_uuid())$$,'22023','invalid_input','cannot omit an active target to hide a missing delivery');
